    "\n"
    "; Safe-Z goto to G30 (Z lifted just above): traverse XY at the safe height, then\n"
    "; move Z. See the matching note on the G30 swap move earlier in this macro.\n"
    "G53 G0 Z-5\n"
    "G53 G0 X#5181 Y#5182\n"
    "G53 G0 Z#5183\n"
    "(PRINT, TC06 EXIT at G30)\n";

static const char *embedded_macro_pcorner =
    "; pcorner.macro - generalized corner XYZ probe for grblHAL (any of the 4 stock corners).\n"
    ";\n"
    "; Safe probing philosophy: probe Z down to DISCOVER the\n"
    "; spoilboard and stock-top heights, never rapid to an assumed Z; decompose every reposition\n"
    "; into an explicit safe-Z lift -> traverse -> descend; route axis-at-a-time around the corner.\n"
    ";\n"
    "; Drop at the root of the SD card / littlefs. Args are passed via GLOBALS set before a NO-ARG call (grblHAL's\n"
    "; O-word CALL does not reliably accept multiple bracketed call args), then invoke:\n"
    ";   #<_ls_corner> = <1-4>     1=FL 2=FR 3=BL 4=BR. Sets the probe-direction signs:\n"
    ";                               sx = +1 for LEFT corners (1,3), -1 for RIGHT (2,4)   (probe toward the X face)\n"
    ";                               sy = +1 for FRONT corners (1,2), -1 for BACK (3,4)   (probe toward the Y face)\n"
    ";   #<_ls_refx>   = machine X of the reference, just OUTSIDE this corner's X face (clear air).\n"
    ";   #<_ls_refy>   = machine Y of the reference, just OUTSIDE this corner's Y face.\n"
    ";   #<_ls_rad>    = probe tip radius (mm).\n"
    ";   #<_ls_spacer> = ACCEPTED AND IGNORED since the DISCOVER path was removed (2026-08-06). It only ever\n"
    ";                   fed the spoilboard-derived floor. The caller now supplies #<_bottom> directly, so a\n"
    ";                   sacrificial backer has to be folded into THAT value by the caller instead.\n"
    ";   #<_ls_thickness> = estimated stock thickness (mm). The X/Y face probes themselves search at a FIXED\n"
    ";                   5mm below the measured top now, not the material midpoint (see #<_start_z> below) - but\n"
    ";                   this is used for the pre-probe APPROACH height (see #<_bottom> + this + #<_ls_plateoffset>\n"
    ";                   below), so the machine doesn't rapid down further than the caller's own best estimate of\n"
    ";                   where the top actually is. Revived 2026-07-27 - was genuinely unused between those two\n"
    ";                   dates (see git history), when the approach height was a blind \"assume <= 1in\" constant.\n"
    ";   #<_ls_topx>, #<_ls_topy>     = offset (mm) from the reference, into the stock, to the stock-top probe\n"
    ";                   XY. Derived from the probing 3D probe's body diameter (StartJobView.BuildProgram) -\n"
    ";                   not stored per fixture. Also reused as the edge probes' anchor (see below) - no separate\n"
    ";                   edge offset is needed since the top-probe XY is already verified to be over solid stock.\n"
    ";   #<_ls_searchf>= fast search feed (mm/min), from the probe definition (Probe/Search feed).\n"
    ";   #<_ls_latchf> = slow latch / re-probe feed (mm/min), from the probe definition (Latch feed).\n"
    ";   #<_ls_startz> = ACCEPTED, no longer selects anything (2026-08-06). It used to pick DISCOVER (>= 9000)\n"
    ";                   vs REUSE; there is now ONE path. Still echoed in the PC ENTER trace so existing logs\n"
    ";                   stay comparable. Every corner probes its OWN stock top, so each reports its own Z\n"
    ";                   (that spread across four corners is the flatness measurement).\n"
    ";   #<_ls_mode>   = 0 = 3D probe (default).\n"
    ";                   1 = touch plate - probes by electrical continuity. Both modes now behave identically\n"
    ";                       here; the distinction only mattered to the removed spoilboard probe, which a\n"
    ";                       continuity probe could not run against a non-conductive board.\n"
    ";   #<_ls_plateoffset> = Z (mm) subtracted from the probed top before it is reported as this corner's Z.\n"
    ";                       0 for the 3D probe, and for a touch plate run directly against conductive stock\n"
    ";                       (no plate, no offset). A separate metal touch plate against non-conductive stock\n"
    ";                       sets this to the plate's own known thickness (ProbeDefinition.PlateThickness).\n"
    ";   #<_ls_lipoffset> = XY (mm) added, toward the stock interior, to the X/Y face probe results before they\n"
    ";                       are reported as this corner's X/Y. 0 for the 3D probe (it touches the real stock\n"
    ";                       edge directly). A touch plate that registers via a lip hooked over the corner (lip\n"
    ";                       resting on/against the stock, its own outer wall set back from the true edge by the\n"
    ";                       lip's depth) probes ITS OWN wall, not the stock's - this shifts the result back to\n"
    ";                       the true edge by that depth (ProbeDefinition.LipWidth). Applied the same direction,\n"
    ";                       and folded into the same radius-compensation term, as #<rad> below.\n"
    ";   #<_ls_edgemargin> = XY (mm) extra clearance, on top of #<_ls_lipoffset> and #<rad>, that the X/Y face-probe\n"
    ";                       descent points back off before dropping to probe depth. lipoffset+rad alone is only\n"
    ";                       exactly enough if the reference (#<rx>/#<ry>) sits EXACTLY at the true edge - but that\n"
    ";                       reference is the CALLER's own estimate, not something this macro has confirmed yet\n"
    ";                       (finding it is the whole point of the face probe about to run), so this pads it.\n"
    ";                       Required (no safe default) - callers should pass 10 unless they have a specific reason\n"
    ";                       not to; a caller that omits it gets 0 (grblHAL's default for an unset global), which\n"
    ";                       is only as safe as the reference itself, no better.\n"
    "; The retreat clearance above a probed corner top (#<_safe_z> below) is a hardcoded 5 mm. It was 20, which\n"
    "; is far more than any real spoilboard/stock variance - on a T-slot extrusion bed even 5 mm would take some\n"
    "; doing - so 20 just spent Z travel on every retreat. A caller with a genuinely known safe height passes\n"
    "; #<_ls_maxz>, which overrides the retreat entirely.\n"
    "; DO NOT make this a caller-supplied global: tried #<_ls_topmargin> on 2026-08-02 and reading a global no\n"
    "; caller had set threw \"error:2 in named sub pcorner.macro\" and aborted the run. Unlike the claim in\n"
    "; #<_ls_edgemargin>'s note below, an unset global is NOT reliably 0 here. If this ever does need to be\n"
    "; caller-driven, guard the read with EXISTS[] the way tc.macro's o199 does for #<_tlo_ref>.\n"
    ";   #<_ls_maxz>   = OPTIONAL machine Z of a known-safe travel height, already trusted by the caller (e.g.\n"
    ";                       the vise's own centre-of-stock probe, run before any corner calls). When > 0, this\n"
    ";                       replaces BOTH the full retract to machine Z0 (o42 below - normally needed so the\n"
    ";                       tool clears clamp/fence hardware between corners, which the vise has none of) and\n"
    ";                       the pre-top-probe descent estimate (o43's #<_approach_z>) with this\n"
    ";                       single known height - the tool never travels above it. 0/unset = old behavior\n"
    ";                       (Corner Fence, no prior stock-top knowledge - safe but more conservative).\n"
    ";   #<_ls_appz>   = OPTIONAL machine Z override for ONLY this call's very first height change (o48 below) -\n"
    ";                       everything else this call still uses #<_ls_maxz>. For a corner reached via a detour\n"
    ";                       that left the fixture's footprint entirely (Corner Fence's TLO-reference park at G30\n"
    ";                       is the current use), so that one return crossing happens at Z0 (always safe) instead\n"
    ";                       of #<_ls_maxz> (only trusted WITHIN the footprint), without losing the trusted height\n"
    ";                       for the rest of this corner's own probe sequence. SENTINEL IS 9999 (\"unset\", not 0) -\n"
    ";                       unlike #<_ls_maxz>, Z0 (machine top) is itself a legitimate override value here, so\n"
    ";                       0 can't double as \"no override\".\n"
    ";   #<_ls_inside> = 0 (default) = OUTSIDE corner/edge - approach from outside the stock, probing inward to\n"
    ";                       find each face (the original/only behavior). 1 = INSIDE corner/edge - probe FROM\n"
    ";                       inside a pocket/step OUTWARD to find each face instead (Start Job's \"Dynamic\" mode\n"
    ";                       inside-corner/inside-edge picks). Implemented as a single sign flip on sx/sy right\n"
    ";                       after they're derived from the corner id - every other line in this macro is already\n"
    ";                       written purely in terms of sx/sy, so nothing else needs to change.\n"
    ";   #<_ls_faces>  = 0 (default) = probe BOTH faces (a full corner - the original/only behavior). 1 = X face\n"
    ";                       ONLY (an edge midpoint on an X-normal face - Start Job's \"Dynamic\" edge-midpoint\n"
    ";                       picks use this to skip the other axis). 2 = Y face ONLY. The skipped axis's output\n"
    ";                       (#<_corner_x> or #<_corner_y>) falls back to the un-probed top-probe anchor - callers\n"
    ";                       doing a single-face pick must not treat that axis as a real touch result. >= 9000 = ignored, use #<_ls_maxz> instead.\n"
    ";\n"
    "; Outputs (GLOBAL named params, survive the SUB):\n"
    ";   #<_corner_x> #<_corner_y>   radius-compensated corner XY (machine coords)\n"
    ";   #<_corner_z>                THIS corner's stock-top Z (machine), less #<_ls_plateoffset> - varies\n"
    ";                                per corner = flatness\n"
    ";   #<_start_z>                 this corner's face-probe depth (top - 5, clamped to #<_ls_zfloor>)\n"
    ";\n"
    "; Preconditions: homed; probe on the main probe input ($6 polarity correct); stock >= 5 mm (the face probes\n"
    ";   now seek at a FIXED 5mm below the measured top, not the material midpoint - thinner stock has its side\n"
    ";   face searched below its own bottom) AND <= ~25 mm (1 in) thick - the stock-top probe now starts just\n"
    ";   above 1 in for speed, so taller stock would be missed; Z probes seek to -140 (keep within $132). The\n"
    ";   the reference must have clear air below it (no fence/clamp) and be >= body-radius\n"
    ";   outside the faces.\n"
    "\n"
    "O<pcorner> SUB\n"
    "  #<rad>    = #1                 ; tip radius = the single CALL arg; rest via globals\n"
    "  #<corner> = #<_ls_corner>\n"
    "  #<rx>     = #<_ls_refx>\n"
    "  #<ry>     = #<_ls_refy>\n"
    "  #<sz_in>  = #<_ls_startz>\n"
    "  #<mode>   = #<_ls_mode>        ; 0 = 3D probe, 1 = touch plate (see file header)\n"
    "  #<maxz>   = #<_ls_maxz>        ; known-safe travel height (machine Z), 0/unset = no prior stock-top knowledge (see file header)\n"
    "  #<appz>   = #<_ls_appz>        ; approach-only override for the FIRST height change below (see file header) - 0/unset = use #<maxz> same as every other height decision this call\n"
    "  #<inside> = #<_ls_inside>      ; 0 = outside corner/edge (default), 1 = inside (see file header)\n"
    "  #<faces>  = #<_ls_faces>       ; 0 = both faces (default), 1 = X face only, 2 = Y face only (see file header)\n"
    "  #<edge_margin> = #<_ls_edgemargin>   ; extra face-probe descent clearance, caller-supplied (see file header)\n"
    "\n"
    "  ; Clear G54 AND cancel any active G92 offset (AND TLO, belt-and-suspenders) so the absolute Z probes\n"
    "  ; below run in TRUE machine coordinates. WCO = G5x offset + G92 offset + TLO (grblHAL gc_get_offset,\n"
    "  ; gcode.c) - G10 L2 P1 alone only zeros the G5x term. Confirmed via a real Start Job failure + reading\n"
    "  ; grblHAL's own report.c (is_g92_active()): a leftover non-zero G92 offset (TLO was already clean -\n"
    "  ; $G showed G49) was the actual cause - a machine Z got driven as if it were a work Z offset by the\n"
    "  ; stray G92, landing the search ~70mm from the real surface instead of the ~12mm it expects, well\n"
    "  ; outside the search's travel cap. (The parameter in that incident, #<_ls_spoilz>, is gone with the\n"
    "  ; spoilboard probe - the failure mode it demonstrates is not, which is why this zeroing stays.)\n"
    "  ; Load Stock sets the real origin from the probed machine coordinates after all corners are done.\n"
    "  G49\n"
    "  G92.1\n"
    "  G10 L2 P1 X0 Y0 Z0\n"
    "\n"
    "  ; --- direction signs from the corner id ---\n"
    "  o10 IF [[#<corner> EQ 1] OR [#<corner> EQ 3]]\n"
    "    #<sx> = 1\n"
    "  o10 ELSE\n"
    "    #<sx> = -1\n"
    "  o10 ENDIF\n"
    "  o11 IF [[#<corner> EQ 1] OR [#<corner> EQ 2]]\n"
    "    #<sy> = 1\n"
    "  o11 ELSE\n"
    "    #<sy> = -1\n"
    "  o11 ENDIF\n"
    "  ; Inside corner/edge (Dynamic mode): flip both signs so the approach comes FROM inside a pocket/step\n"
    "  ; OUTWARD to each face, instead of from outside the stock inward. Everything below this point is already\n"
    "  ; written purely in terms of sx/sy, so this single flip is the whole difference.\n"
    "  o12 IF [#<inside> EQ 1]\n"
    "    #<sx> = 0 - #<sx>\n"
    "    #<sy> = 0 - #<sy>\n"
    "  o12 ENDIF\n"
    "  (PRINT, PC ENTER corner=#<corner> sx=#<sx> sy=#<sy> rad=#<rad> rx=#<rx> ry=#<ry> startz=#<sz_in> inside=#<inside> faces=#<faces>)\n"
    "  ; Echo EVERY remaining input, here, before the first motion of the call. Two reasons this is worth the\n"
    "  ; six lines. A probed corner that comes out wrong is otherwise un-diagnosable after the fact: the caller's\n"
    "  ; parameters live in the sender and the log only showed the handful above, so \"the macro did what it was\n"
    "  ; told\" and \"the caller told it the wrong thing\" looked identical. And these lines READ each global, so a\n"
    "  ; parameter the caller forgot to set now fails HERE - before the tool has moved - naming itself, instead\n"
    "  ; of aborting mid-probe (see the error:2 note in the header) or, worse, silently reading as something.\n"
    "  ; Split across several PRINTs rather than one: grblHAL's line buffer is finite and a truncated trace is\n"
    "  ; a trace you cannot trust. The ENTER line above is deliberately left untouched so older logs still diff.\n"
    "  (PRINT, PC IN2 mode=#<mode> maxz=#<maxz> appz=#<appz> edgemargin=#<edge_margin>)\n"
    "  (PRINT, PC IN3 bottom=#<_bottom> thickness=#<_ls_thickness> zfloor=#<_ls_zfloor>)\n"
    "  (PRINT, PC IN4 plateoffset=#<_ls_plateoffset> lipoffset=#<_ls_lipoffset>)\n"
    "  (PRINT, PC IN5 topx=#<_ls_topx> topy=#<_ls_topy>)\n"
    "  (PRINT, PC IN6 searchf=#<_ls_searchf> latchf=#<_ls_latchf>)\n"
    "  (PRINT, PC IN7 spacer=#<_ls_spacer> - accepted and ignored, see header)\n"
    "\n"
    "\n"
    "\n"
    "  ; ================= stock-top Z at THIS corner (EVERY corner -> flatness) =================\n"
    "  ; Move the fixture type's top-probe offset (#<_ls_topx>/#<_ls_topy>) into the stock interior (sign per\n"
    "  ; corner) and probe the top, so each corner reports its own Z - the spread across the four corners is\n"
    "  ; the stock/spoilboard flatness. #<_topx>/#<_topy> persist as the edge probes' anchor below.\n"
    "  ; Pre-probe approach clearance above the floor (#<_bottom>): the caller's own best estimate of stock\n"
    "  ; thickness plus, when running a touch plate, the plate's own thickness sitting on top of the stock - so\n"
    "  ; this scales with what's ACTUALLY there instead of blindly assuming worst-case 1in (25.4mm) material\n"
    "  ; regardless of real thickness. +10 is a fixed safety margin against estimate error (same spirit as the\n"
    "  ; entered-width/height \"estimate should be a few mm larger than actual\" guidance elsewhere). Confirmed on\n"
    "  ; real hardware 2026-07-27: with a 3/4in stock + 1/4in spacer + 12mm touch plate, the OLD blind \"+30\"\n"
    "  ; barely cleared the stock and did not clear the touch plate at all - a real collision risk.\n"
    "  #<_approach_z> = [#<_bottom> + #<_ls_thickness> + #<_ls_plateoffset> + 10]\n"
    "  G90\n"
    "  ; NE 0, not GT 0 (2026-07 bug, confirmed on real hardware on both this path and o43 below): #<maxz> is a\n"
    "  ; MACHINE Z coordinate, and on a machine that homes Z to the top (Z0) with the whole work envelope below\n"
    "  ; that, every real value here is NEGATIVE - \"GT 0\" silently failed for every legitimate maxz the caller\n"
    "  ; ever passed (the vise's own #<_lv_safe_z>, Corner Fence's #<c1_maxz>), falling through to the ELSE\n"
    "  ; branch every time with no error, just quietly slower/more conservative than intended.\n"
    "  ;\n"
    "  ; #<appz> (caller-optional, see file header) overrides ONLY this first move - everything else this call\n"
    "  ; (the pre-top-probe descent below, the final retreat) still uses the caller's real #<maxz>, same as\n"
    "  ; every other corner. Needed for a corner reached via a detour that left the fixture's footprint entirely\n"
    "  ; (e.g. Corner Fence's TLO-reference park at G30, not verified clear of fence/clamp hardware) - #<maxz>\n"
    "  ; is only trusted WITHIN the footprint (verified by an earlier corner's own measurement), so that one\n"
    "  ; return crossing must happen at Z0 instead, without also giving up the trusted height for the rest of\n"
    "  ; this corner's own probe sequence. Sentinel is 9999 (\"unset\"), NOT 0 - unlike #<maxz>, Z0 (machine top)\n"
    "  ; is itself a legitimate override value here (that's the whole point), so 0 can't double as \"no override\".\n"
    "  o48 IF [#<appz> LT 9000]\n"
    "    G53 G0 Z[#<appz>]\n"
    "  o48 ELSE\n"
    "  o42 IF [#<maxz> NE 0]\n"
    "    G53 G0 Z[#<maxz>]             ; rapid - caller already knows a trusted safe height (e.g. the vise's own centre probe) - never go any higher than necessary\n"
    "  o42 ELSE\n"
    "    G53 G0 Z0                     ; rapid - later corners: retract FULLY to machine top before crossing to the next corner - safer than just above the previous corner's stock in case there's clamp/fence hardware in between\n"
    "  o42 ENDIF\n"
    "  o48 ENDIF\n"
    "  #<_topx> = [#<rx> + [#<_ls_topx> * #<sx>]]\n"
    "  #<_topy> = [#<ry> + [#<_ls_topy> * #<sy>]]\n"
    "  G53 G0 X[#<_topx>] Y[#<_topy>]    ; rapid - travelling AT the safe height set above\n"
    "  ; Descend to a safe height before this corner's own top probe - NOT #<_safe_z>, which still holds the\n"
    "  ; PREVIOUS corner's height (top+20) at this point in the code (this corner's own top probe, which\n"
    "  ; recomputes it, hasn't run yet). Flatness/spacer variance between corners means the previous corner's\n"
    "  ; safe height can sit below THIS corner's actual top - a bare G0 rapid to a stale height would drive\n"
    "  ; straight into solid stock with nothing to catch it. If the caller already knows a trusted height\n"
    "  ; (#<maxz>, e.g. the vise's own centre probe) use that directly; otherwise fall back to the same\n"
    "  ; thickness/plate-aware #<_approach_z> computed above (same reasoning) -\n"
    "  ; this is the branch a Corner Fence's OWN corner 1 actually takes (it has no #<c1_maxz> yet - that's\n"
    "  ; only computed AFTER corner 1 finishes, for corners 2-4 to use), so this is exactly what needed fixing.\n"
    "  o43 IF [#<maxz> NE 0]\n"
    "    G53 G0 Z[#<maxz>]\n"
    "  o43 ELSE\n"
    "    G53 G0 Z[#<_approach_z>]\n"
    "  o43 ENDIF\n"
    "  ; SAFETY + early-out. The stock top always sits ABOVE the effective floor (spoilboard + spacer), so bound\n"
    "  ; this seek instead of driving to a deep machine target - a dead/mis-wired probe then alarms near the board\n"
    "  ; instead of ploughing to -140. Corners are placed from the ESTIMATED size, so cap them at the floor: a real corner triggers on the\n"
    "  ; material above it, but a corner left over BARE board (estimate too big) reaches the floor with nothing\n"
    "  ; there and G38.2 aborts right away - no doomed side search into air. The spacer band guarantees the cap\n"
    "  ; clears the board (floor > spoilboard); with spacer 0 the +1 keeps it a hair above the board.\n"
    "  G38.2 Z[#<_bottom> + 1] F[#<_ls_searchf>]        ; refuse to seek below the caller's material floor\n"
    "  G91 G1 Z2 F1000\n"
    "  G38.2 Z-5 F[#<_ls_latchf>]\n"
    "  #<_z_top> = #5063\n"
    "  #<_safe_z> = [#<_z_top> + 5]      ; safe travel height now known: 5 mm above this corner's top\n"
    "  ; Repositioning within this corner (the X-face and Y-face retreats, and the exit retreat below) prefer the\n"
    "  ; CALLER'S trusted #<maxz> (e.g. the operator-set Corner travel margin, or the vise's own centre probe) over\n"
    "  ; freshly recomputing _safe_z - when the caller has one, it's a single, predictable height good for the\n"
    "  ; whole run, not a per-corner value that changes call to call for no reason the operator can see. #<_safe_z>\n"
    "  ; itself is still always computed (needed as the fallback here, and as what a LATER corner call reads via\n"
    "  ; #<maxz> once it's been threaded back out by the caller).\n"
    "  #<_retreat_z> = #<_safe_z>\n"
    "  o44 IF [#<maxz> NE 0]\n"
    "    #<_retreat_z> = #<maxz>\n"
    "  o44 ENDIF\n"
    "  G91 G1 Z10 F1000\n"
    "  G90\n"
    "  (PRINT, PC z_top=#<_z_top>)\n"
    "\n"
    "  ; ================= start_z for the face probes (fixed 5mm below the measured top) =================\n"
    "  ; Was top - thickness/2 (material midpoint) - changed to a fixed 5mm inset (2026-07-20, user request):\n"
    "  ; simpler and independent of the caller's estimated #<_ls_thickness>, which is only ever an estimate\n"
    "  ; before Measure has actually run. 5mm clears a top chamfer/rounded edge on any stock thick enough to\n"
    "  ; probe at all (preconditions require >= 3mm... clamped up to the zfloor safety below regardless).\n"
    "  #<_start_z> = [#<_z_top> - 5]\n"
    "  ; SAFETY: never position the probe below the machine's Z soft-limit floor (#<_ls_zfloor>, passed by Load Stock\n"
    "  ; from $132). When the stock sits low - its top near the Z travel bottom - start_z can fall below\n"
    "  ; reachable Z, and the G53 G1 descent to it trips Alarm:2 (soft limit). Clamp up to the floor; the side face is\n"
    "  ; still contacted since the face seek is horizontal from start_z.\n"
    "  o32 IF [#<_start_z> LT #<_ls_zfloor>]\n"
    "    #<_start_z> = #<_ls_zfloor>\n"
    "  o32 ENDIF\n"
    "  (PRINT, PC start_z=#<_start_z>)\n"
    "\n"
    "  ; Fallback outputs for a face this call skips (faces=1/2, Dynamic mode edge-midpoint picks) - the\n"
    "  ; un-probed axis reports the top-probe anchor, NOT a real touch. Overwritten below when that face's\n"
    "  ; block actually runs.\n"
    "  #<_corner_x> = #<_topx>\n"
    "  #<_corner_y> = #<_topy>\n"
    "\n"
    "  ; ================= X face probe (skipped when #<faces> EQ 2 - Y face only) =================\n"
    "  o90 IF [#<faces> NE 2]\n"
    "  ; From the top-probe position (over solid stock, verified above) move ONLY X back out to the reference\n"
    "  ; (the face) - Y unchanged, so the pre-seek position is anchored to a point already known to be over\n"
    "  ; material rather than a separately estimated offset. Descend to start_z, then seek toward the face.\n"
    "  ; #<rx> alone (the fixture's saved reference) was calibrated to clear a 3D probe's BODY diameter - a touch\n"
    "  ; plate's lip sticks out #<_ls_lipoffset> mm FURTHER than that, so the vertical descent right below needs\n"
    "  ; the SAME extra outward push, or it can land right at (or on top of) the plate's own wall instead of in\n"
    "  ; clear air. Subtracting [lipoffset + rad + edge_margin]*sx moves it outward (opposite sx's interior-pointing\n"
    "  ; convention). rad+lipoffset alone is only exactly enough clearance if #<rx> sits EXACTLY at the true edge -\n"
    "  ; but #<rx> is the caller's own estimate, not something this macro has verified yet (that's the whole point\n"
    "  ; of the face probe about to run), so #<edge_margin> pads it - shooting blind at an unconfirmed edge needs\n"
    "  ; slop, not a razor-thin geometric calculation. MUST include #<rad>, not just lipoffset: lipoffset alone only\n"
    "  ; clears the plate with the bit's CENTER, not its full diameter. Confirmed on real hardware 2026-07-30 (an\n"
    "  ; 8mm bit's center landed exactly on the plate's edge, half the bit still over it, and the descent to\n"
    "  ; start_z caught the edge). The later G38.2 target is untouched (still an absolute #<rx> + 35*sx) - starting\n"
    "  ; further out just means it travels a bit further to reach the same target.\n"
    "  G53 G0 Z[#<_retreat_z>]           ; rapid - the trusted known-safe height when the caller has one, else just above this corner's own top (VERIFIED by the probe just run)\n"
    "  G53 G0 X[#<rx> - [[#<_ls_lipoffset> + #<rad> + #<edge_margin>] * #<sx>]] Y[#<_topy>]       ; rapid - travelling AT the verified safe height\n"
    "  G53 G0 Z[#<_z_top> + 12]          ; rapid down to within 12mm of the KNOWN top (just probed) - controlled feed only takes over for the final approach\n"
    "  G53 G1 F1000 Z[#<_start_z>]       ; controlled - final descent to the face-probe depth\n"
    "  ; ABSOLUTE seeks (not G91): a G91 move right after a G53 mis-computes on a $23-inverted axis\n"
    "  ; (firmware bug - target sign-flips -> false Alarm:2). Current X is #<rx>, so seek to an absolute X.\n"
    "  G38.2 X[#<rx> + [35 * #<sx>]] F[#<_ls_searchf>]      ; coarse seek toward the X face\n"
    "  #<x_c1> = #5061\n"
    "  G1 X[#<x_c1> - [4 * #<sx>]] F1000                    ; back off so the deflecting ball RELEASES before the slow re-probe (G1: gentle, no rapid-accel jerk)\n"
    "  G38.2 X[#<x_c1> + [6 * #<sx>]] F[#<_ls_latchf>]      ; slow re-probe (2 mm back-off left it stuck triggered -> Alarm:4; 4 mm clears it)\n"
    "  #<x_trig> = #5061\n"
    "  G1 X[#<x_trig> - [10 * #<sx>]] F1000\n"
    "  G90\n"
    "  (PRINT, PC x_trig=#<x_trig>)\n"
    "  ; #<_ls_lipoffset> folds into the SAME term as the probe tip radius - both push the reported edge back\n"
    "  ; toward the interior by a fixed amount, for the same reason (the probed surface isn't the true edge\n"
    "  ; itself); 0 for the 3D probe, so this is a no-op there.\n"
    "  #<_corner_x> = [#<x_trig> + [[#<rad> + #<_ls_lipoffset>] * #<sx>]]\n"
    "  o90 ENDIF\n"
    "\n"
    "  ; ================= Y face probe (skipped when #<faces> EQ 1 - X face only) =================\n"
    "  o91 IF [#<faces> NE 1]\n"
    "  ; Retract to a trusted safe height first - the X face probe left the tip near start_z (probing depth), so\n"
    "  ; crossing at that depth would drag the tip across the stock top. Once at that height, go straight (X AND Y\n"
    "  ; together) to the Y-face-start position (topx, ry) - no need to detour via the top-probe XY (topx, topy)\n"
    "  ; first: that routing was only needed because the OLD retreat height was this corner's own freshly-computed\n"
    "  ; _safe_z, not independently verified clear of the stock along an arbitrary diagonal. #<_retreat_z> (above)\n"
    "  ; is either that same _safe_z or the caller's own trusted height - both are clear of the stock everywhere in\n"
    "  ; the vicinity, not just directly above the last probed point, so a diagonal move at that height is exactly\n"
    "  ; as safe as the old axis-at-a-time routing, just one move instead of two.\n"
    "  ; Same lip+radius+margin clearance push as the X face start above - see its comment.\n"
    "  G53 G0 Z[#<_retreat_z>]           ; rapid - verified/trusted safe height (see X face above)\n"
    "  G53 G0 X[#<_topx>] Y[#<ry> - [[#<_ls_lipoffset> + #<rad> + #<edge_margin>] * #<sy>]]       ; rapid - diagonal, straight to the Y-face-start position, AT that height\n"
    "  G53 G0 Z[#<_z_top> + 12]          ; rapid down to within 12mm of the KNOWN top (see X face above)\n"
    "  G53 G1 F1000 Z[#<_start_z>]       ; controlled - final descent to the face-probe depth\n"
    "  ; ABSOLUTE seeks (see X face) - current Y is #<ry>, so seek to an absolute Y.\n"
    "  G38.2 Y[#<ry> + [35 * #<sy>]] F[#<_ls_searchf>]      ; coarse seek toward the Y face\n"
    "  #<y_c1> = #5062\n"
    "  G1 Y[#<y_c1> - [4 * #<sy>]] F1000                    ; back off before the slow re-probe (G1: gentle, no rapid-accel jerk)\n"
    "  G38.2 Y[#<y_c1> + [6 * #<sy>]] F[#<_ls_latchf>]      ; slow re-probe\n"
    "  #<y_trig> = #5062\n"
    "  G1 Y[#<y_trig> - [10 * #<sy>]] F1000\n"
    "  G90\n"
    "  (PRINT, PC y_trig=#<y_trig>)\n"
    "  ; #<_ls_lipoffset> folds into the SAME term as the probe tip radius - both push the reported edge back\n"
    "  ; toward the interior by a fixed amount, for the same reason (the probed surface isn't the true edge\n"
    "  ; itself); 0 for the 3D probe, so this is a no-op there.\n"
    "  #<_corner_y> = [#<y_trig> + [[#<rad> + #<_ls_lipoffset>] * #<sy>]]\n"
    "  o91 ENDIF\n"
    "\n"
    "  ; ================= outputs =================\n"
    "  #<_corner_z> = [#<_z_top> - #<_ls_plateoffset>]   ; 0 for the 3D probe and touch-plate-on-conductive-stock (no-op)\n"
    "  (PRINT, PC OUT c=#<corner> x=#<_corner_x> y=#<_corner_y> z=#<_corner_z>)\n"
    "\n"
    "  ; retract before returning to the caller - the next corner travels at this height. Rapid: #<_retreat_z> is\n"
    "  ; either a VERIFIED height (20mm above this corner's just-probed top) or the caller's own trusted one, so\n"
    "  ; this retract only ever moves AWAY from material, never toward it.\n"
    "  G53 G0 Z[#<_retreat_z>]\n"
    "  (PRINT, PC EXIT)\n"
    "O<pcorner> ENDSUB\n";

static const char *embedded_macro_pvisecorner =
    "; pvisecorner.macro - probes a machinist vise's FIXED JAW front-left corner for grblHAL.\n"
    ";\n"
    "; Unlike pcorner.macro (which needs its reference OUTSIDE both faces, over open spoilboard), this macro's\n"
    "; reference sits OVER the jaw interior, near the corner - the FixtureEditDialog schematic's clearance circle\n"
    "; is centered there, with the corner on its boundary. That's the opposite geometry, so this is its own macro\n"
    "; rather than a variant of pcorner: probe the jaw top DIRECTLY at the reference (no separate spoilboard probe -\n"
    "; the jaw is rigid and bolted down, so its own top is the only surface that matters), then for each face back\n"
    "; OFF outward (away from the jaw interior) to clear air, descend, and seek back INWARD to find it - the mirror\n"
    "; image of pcorner's outside-in approach.\n"
    ";\n"
    "; Args via GLOBALS set before a NO-ARG call (grblHAL's O-word CALL does not reliably accept multiple bracketed\n"
    "; args), then invoke:\n"
    ";   #<_lv_refx>, #<_lv_refy>, #<_lv_refz> = machine position jogged over the jaw, near its front-left corner,\n"
    ";                   within the schematic's clearance circle AND within ~10 mm above the jaw top.\n"
    ";   #<_lv_rad>    = probe tip radius (mm).\n"
    ";   #<_lv_clear>  = distance (mm) to back off OUTWARD (away from the jaw) from the reference before each face\n"
    ";                   seek - must clear the probe body off the corner, same idea as pcorner's topx/topy offset.\n"
    ";   #<_lv_searchf>= fast search feed (mm/min), from the 3D probe definition (Probe/Search feed).\n"
    ";   #<_lv_latchf> = slow latch / re-probe feed (mm/min), from the 3D probe definition (Latch feed).\n"
    ";   #<_lv_zfloor> = machine Z soft-limit floor (machine coords) - never position the probe below this.\n"
    ";\n"
    "; Outputs (GLOBAL named params, survive the SUB):\n"
    ";   #<_corner_x> #<_corner_y>   radius-compensated jaw corner XY (machine coords)\n"
    ";   #<_corner_z>                the jaw's top Z (machine) at the reference\n"
    ";\n"
    "; Preconditions: homed; probe on the main probe input ($6 polarity correct); the reference must be within\n"
    "; ~10 mm above the jaw top (the top-probe search is capped 12 mm below it) and clear of both faces by less\n"
    "; than #<_lv_clear> (so backing off #<_lv_clear> outward truly reaches open air beside the jaw).\n"
    "\n"
    "O<pvisecorner> SUB\n"
    "  #<rad> = #1                    ; tip radius = the single CALL arg; rest via globals\n"
    "  #<rx>  = #<_lv_refx>\n"
    "  #<ry>  = #<_lv_refy>\n"
    "  #<rz>  = #<_lv_refz>\n"
    "\n"
    "  ; Clear G54 AND cancel any active G92 offset (AND TLO, belt-and-suspenders) so the absolute Z probes\n"
    "  ; below run in TRUE machine coordinates (same reasoning/fix as pcorner.macro - a leftover non-zero\n"
    "  ; G92 offset was confirmed as the actual cause via grblHAL's own $G/report.c; G10 L2 P1 alone never\n"
    "  ; touches G92).\n"
    "  G49\n"
    "  G92.1\n"
    "  G10 L2 P1 X0 Y0 Z0\n"
    "  G90\n"
    "  (PRINT, PV ENTER rx=#<rx> ry=#<ry> rz=#<rz> rad=#<rad> clear=#<_lv_clear>)\n"
    "  ; The rest of the inputs, before the first motion - same reasoning as pcorner.macro's IN2..IN7 block.\n"
    "  (PRINT, PV IN2 searchf=#<_lv_searchf> latchf=#<_lv_latchf> zfloor=#<_lv_zfloor>)\n"
    "\n"
    "  ; ================= jaw top Z, probed directly at the reference (already over the jaw) =================\n"
    "  G53 G0 Z0                    ; rapid - Z0 is the machine top, always clear\n"
    "  G53 G0 X[#<rx>] Y[#<ry>]     ; rapid - travelling AT Z0\n"
    "  G53 G1 F1000 Z[#<rz>]        ; controlled - descending toward the (unverified) jogged reference, near the jaw\n"
    "  ; SAFETY: cap the search 12 mm below the reference, same reasoning as pcorner.macro's spoilboard/top probes -\n"
    "  ; a dead/mis-wired probe alarms near the jaw instead of ploughing on.\n"
    "  G38.2 Z[#<rz> - 12] F[#<_lv_searchf>]\n"
    "  G91 G1 Z2 F1000\n"
    "  G38.2 Z-5 F[#<_lv_latchf>]\n"
    "  #<_top_z> = #5063\n"
    "  G91 G1 Z10 F1000\n"
    "  G90\n"
    "  (PRINT, PV top_z=#<_top_z>)\n"
    "  #<_safe_z>  = [#<_top_z> + 20]   ; safe travel height: 20 mm above the jaw top\n"
    "  #<_start_z> = [#<_top_z> - 4]    ; face-seek height: centre tip 4 mm below the jaw top\n"
    "  o10 IF [#<_start_z> LT #<_lv_zfloor>]\n"
    "    #<_start_z> = #<_lv_zfloor>\n"
    "  o10 ENDIF\n"
    "  (PRINT, PV start_z=#<_start_z>)\n"
    "\n"
    "  ; ================= X face (jaw's left end) =================\n"
    "  ; Back off OUTWARD (left, -X) from the reference by #<_lv_clear> - clear of the jaw - then descend and seek\n"
    "  ; back INWARD (+X) to find the face. Mirror image of pcorner's X-face section.\n"
    "  G53 G0 Z[#<_safe_z>]                            ; rapid - VERIFIED height, just probed\n"
    "  G53 G0 X[#<rx> - #<_lv_clear>] Y[#<ry>]         ; rapid - travelling AT that height\n"
    "  G53 G0 Z[#<_top_z> + 12]                        ; rapid down to within 12mm of the KNOWN top (just probed) - controlled feed only takes over for the final approach\n"
    "  G53 G1 F1000 Z[#<_start_z>]                     ; controlled - final descent to the face-probe depth\n"
    "  G38.2 X[#<rx> + 20] F[#<_lv_searchf>]           ; coarse seek back toward/past the reference\n"
    "  #<x_c1> = #5061\n"
    "  G1 X[#<x_c1> - 4] F1000                         ; back off so the deflecting ball releases before the slow re-probe\n"
    "  G38.2 X[#<x_c1> + 6] F[#<_lv_latchf>]           ; slow re-probe\n"
    "  #<x_trig> = #5061\n"
    "  G1 X[#<x_trig> - 10] F1000\n"
    "  G90\n"
    "  (PRINT, PV x_trig=#<x_trig>)\n"
    "\n"
    "  ; ================= Y face (jaw's clamping face, front) =================\n"
    "  ; Retract to safe Z before crossing back over the jaw (same reasoning as pcorner: never traverse at probing\n"
    "  ; depth over solid material). Back off OUTWARD (front, -Y) by #<_lv_clear>, descend, seek back INWARD (+Y).\n"
    "  G53 G0 Z[#<_safe_z>]                            ; rapid - VERIFIED height (see X face above)\n"
    "  G53 G0 X[#<rx>] Y[#<ry> - #<_lv_clear>]         ; rapid - travelling AT that height\n"
    "  G53 G0 Z[#<_top_z> + 12]                        ; rapid down to within 12mm of the KNOWN top (see X face above)\n"
    "  G53 G1 F1000 Z[#<_start_z>]                     ; controlled - final descent to the face-probe depth\n"
    "  G38.2 Y[#<ry> + 20] F[#<_lv_searchf>]\n"
    "  #<y_c1> = #5062\n"
    "  G1 Y[#<y_c1> - 4] F1000\n"
    "  G38.2 Y[#<y_c1> + 6] F[#<_lv_latchf>]\n"
    "  #<y_trig> = #5062\n"
    "  G1 Y[#<y_trig> - 10] F1000\n"
    "  G90\n"
    "  (PRINT, PV y_trig=#<y_trig>)\n"
    "\n"
    "  ; ================= outputs (radius compensated) =================\n"
    "  #<_corner_x> = [#<x_trig> + #<rad>]\n"
    "  #<_corner_y> = [#<y_trig> + #<rad>]\n"
    "  #<_corner_z> = #<_top_z>\n"
    "  (PRINT, PV OUT x=#<_corner_x> y=#<_corner_y> z=#<_corner_z>)\n"
    "\n"
    "  ; retract to just above the jaw top - rapid: _safe_z is VERIFIED (20mm above the just-probed top), so this\n"
    "  ; only ever moves AWAY from the jaw, never toward it.\n"
    "  G53 G0 Z[#<_safe_z>]\n"
    "  (PRINT, PV EXIT)\n"
    "O<pvisecorner> ENDSUB\n";

static const char *embedded_macro_pcenter =
    "; pcenter.macro - center finder for grblHAL (Start Job \"Dynamic\" mode center dot).\n"
    ";\n"
    "; PROTOTYPE (2026-07-26): unlike pcorner.macro, this does NOT auto-discover its own probing Z depth -\n"
    "; the caller must already know a safe Z (machine coords) to seek at before calling. For a solid boss that's\n"
    "; a quick single top-probe the caller runs first (same idea as pcorner's DISCOVER pass); for a hole it MUST\n"
    "; be a depth the operator trusts is below the surrounding surface and above the hole's floor - there is no\n"
    "; safe way to auto-discover that (a probe centered over an open/through hole may never trigger downward at\n"
    "; all). Rough edge, called out deliberately rather than papered over - see the Start Job Dynamic-mode plan.\n"
    ";\n"
    "; Args (globals, same \"set globals then bare CALL\" idiom as pcorner.macro - grblHAL's O-word CALL does not\n"
    "; reliably accept multiple bracketed args):\n"
    ";   #<_ls_rad>     = probe tip radius (mm).\n"
    ";   #<_ls_refx/refy> = machine XY of the estimated center (jog target - the green center dot).\n"
    ";   #<_ls_startz>  = machine Z to seek at (see PROTOTYPE note above - caller-supplied, not discovered here).\n"
    ";   #<_ls_wpx>, #<_ls_wpy> = estimated boss/hole size (mm) along X and Y - diameter for round, width/height\n"
    ";                    otherwise. Same field either way; a non-round hole is NOT specially handled (2026-07-26\n"
    ";                    prototype scope - see the Dynamic-mode plan's \"not round\" caveat).\n"
    ";   #<_ls_center_mode> = 0 = OUTSIDE (solid boss - probe inward from clearance outside the estimated size).\n"
    ";                        1 = INSIDE (hole - probe outward from near-center to the estimated wall).\n"
    ";   #<_ls_clear>   = clearance/inset (mm) - how far outside (mode 0) or short of (mode 1) the estimated\n"
    ";                    size the initial position sits, same role as pcorner's XYClearance.\n"
    ";   #<_ls_searchf>, #<_ls_latchf> = fast/slow probe feeds (from the probe definition, same as pcorner).\n"
    ";\n"
    "; Outputs (GLOBAL named params, survive the SUB):\n"
    ";   #<_center_x>, #<_center_y> = the found center, machine coords, radius-compensated.\n"
    "\n"
    "O<pcenter> SUB\n"
    "  #<rad>   = #1\n"
    "  #<rx>    = #<_ls_refx>\n"
    "  #<ry>    = #<_ls_refy>\n"
    "  #<z>     = #<_ls_startz>\n"
    "  #<wpx>   = #<_ls_wpx>\n"
    "  #<wpy>   = #<_ls_wpy>\n"
    "  #<mode>  = #<_ls_center_mode>\n"
    "  #<clear> = #<_ls_clear>\n"
    "  (PRINT, PCTR ENTER mode=#<mode> rx=#<rx> ry=#<ry> z=#<z> wpx=#<wpx> wpy=#<wpy>)\n"
    "  ; The rest of the inputs, before the first motion - same reasoning as pcorner.macro's IN2..IN7 block:\n"
    "  ; a probed centre that comes out wrong is otherwise indistinguishable from a caller that passed the\n"
    "  ; wrong numbers, and reading them here makes an unset one fail before the tool moves.\n"
    "  (PRINT, PCTR IN2 rad=#<rad> clear=#<clear> searchf=#<_ls_searchf> latchf=#<_ls_latchf>)\n"
    "\n"
    "  G49\n"
    "  G92.1\n"
    "  G10 L2 P1 X0 Y0 Z0\n"
    "  G90\n"
    "\n"
    "  o10 IF [#<mode> EQ 0]\n"
    "    ; OUTSIDE (solid boss): start clear of the estimated size on the -X side, drop to the probing depth,\n"
    "    ; seek INWARD (+X) to find the near face; cross to the +X side, seek INWARD (-X) for the far face.\n"
    "    #<x0> = [#<rx> - [#<wpx> / 2 + #<clear>]]\n"
    "    G53 G0 X[#<x0>] Y[#<ry>]\n"
    "    G53 G0 Z[#<z>]\n"
    "    G38.2 X[#<rx>] F[#<_ls_searchf>]\n"
    "    #<xa> = #5061\n"
    "    G1 X[#<xa> - 4] F1000\n"
    "    G38.2 X[#<xa> + 6] F[#<_ls_latchf>]\n"
    "    #<x_near> = #5061\n"
    "    G1 X[#<x_near> - 10] F1000\n"
    "    (PRINT, PCTR x_near=#<x_near>)\n"
    "\n"
    "    #<x1> = [#<rx> + [#<wpx> / 2 + #<clear>]]\n"
    "    G53 G0 X[#<x1>] Y[#<ry>]\n"
    "    G38.2 X[#<rx>] F[#<_ls_searchf>]\n"
    "    #<xb> = #5061\n"
    "    G1 X[#<xb> + 4] F1000\n"
    "    G38.2 X[#<xb> - 6] F[#<_ls_latchf>]\n"
    "    #<x_far> = #5061\n"
    "    G1 X[#<x_far> + 10] F1000\n"
    "    (PRINT, PCTR x_far=#<x_far>)\n"
    "\n"
    "    #<y0> = [#<ry> - [#<wpy> / 2 + #<clear>]]\n"
    "    G53 G0 X[#<rx>] Y[#<y0>]\n"
    "    G38.2 Y[#<ry>] F[#<_ls_searchf>]\n"
    "    #<ya> = #5062\n"
    "    G1 Y[#<ya> - 4] F1000\n"
    "    G38.2 Y[#<ya> + 6] F[#<_ls_latchf>]\n"
    "    #<y_near> = #5062\n"
    "    G1 Y[#<y_near> - 10] F1000\n"
    "    (PRINT, PCTR y_near=#<y_near>)\n"
    "\n"
    "    #<y1> = [#<ry> + [#<wpy> / 2 + #<clear>]]\n"
    "    G53 G0 X[#<rx>] Y[#<y1>]\n"
    "    G38.2 Y[#<ry>] F[#<_ls_searchf>]\n"
    "    #<yb> = #5062\n"
    "    G1 Y[#<yb> + 4] F1000\n"
    "    G38.2 Y[#<yb> - 6] F[#<_ls_latchf>]\n"
    "    #<y_far> = #5062\n"
    "    G1 Y[#<y_far> + 10] F1000\n"
    "    (PRINT, PCTR y_far=#<y_far>)\n"
    "\n"
    "    #<_center_x> = [[#<x_near> + #<x_far>] / 2]\n"
    "    #<_center_y> = [[#<y_near> + #<y_far>] / 2]\n"
    "  o10 ELSE\n"
    "    ; INSIDE (hole): start near-center but inset short of the estimated wall by the clearance, seek\n"
    "    ; OUTWARD (away from center) to find each wall.\n"
    "    #<x0> = [#<rx> - [#<wpx> / 2 - #<clear>]]\n"
    "    G53 G0 X[#<x0>] Y[#<ry>]\n"
    "    G53 G0 Z[#<z>]\n"
    "    G38.2 X[#<x0> - [2 * #<clear>]] F[#<_ls_searchf>]\n"
    "    #<xa> = #5061\n"
    "    G1 X[#<xa> + 4] F1000\n"
    "    G38.2 X[#<xa> - 6] F[#<_ls_latchf>]\n"
    "    #<x_near> = #5061\n"
    "    G1 X[#<x_near> + 10] F1000\n"
    "    (PRINT, PCTR x_near=#<x_near>)\n"
    "\n"
    "    #<x1> = [#<rx> + [#<wpx> / 2 - #<clear>]]\n"
    "    G53 G0 X[#<x1>] Y[#<ry>]\n"
    "    G38.2 X[#<x1> + [2 * #<clear>]] F[#<_ls_searchf>]\n"
    "    #<xb> = #5061\n"
    "    G1 X[#<xb> - 4] F1000\n"
    "    G38.2 X[#<xb> + 6] F[#<_ls_latchf>]\n"
    "    #<x_far> = #5061\n"
    "    G1 X[#<x_far> - 10] F1000\n"
    "    (PRINT, PCTR x_far=#<x_far>)\n"
    "\n"
    "    #<y0> = [#<ry> - [#<wpy> / 2 - #<clear>]]\n"
    "    G53 G0 X[#<rx>] Y[#<y0>]\n"
    "    G38.2 Y[#<y0> - [2 * #<clear>]] F[#<_ls_searchf>]\n"
    "    #<ya> = #5062\n"
    "    G1 Y[#<ya> + 4] F1000\n"
    "    G38.2 Y[#<ya> - 6] F[#<_ls_latchf>]\n"
    "    #<y_near> = #5062\n"
    "    G1 Y[#<y_near> + 10] F1000\n"
    "    (PRINT, PCTR y_near=#<y_near>)\n"
    "\n"
    "    #<y1> = [#<ry> + [#<wpy> / 2 - #<clear>]]\n"
    "    G53 G0 X[#<rx>] Y[#<y1>]\n"
    "    G38.2 Y[#<y1> + [2 * #<clear>]] F[#<_ls_searchf>]\n"
    "    #<yb> = #5062\n"
    "    G1 Y[#<yb> - 4] F1000\n"
    "    G38.2 Y[#<yb> + 6] F[#<_ls_latchf>]\n"
    "    #<y_far> = #5062\n"
    "    G1 Y[#<y_far> - 10] F1000\n"
    "    (PRINT, PCTR y_far=#<y_far>)\n"
    "\n"
    "    #<_center_x> = [[#<x_near> + #<x_far>] / 2]\n"
    "    #<_center_y> = [[#<y_near> + #<y_far>] / 2]\n"
    "  o10 ENDIF\n"
    "\n"
    "  G90\n"
    "  G53 G0 Z[#<z> + 20]\n"
    "  (PRINT, PCTR OUT x=#<_center_x> y=#<_center_y>)\n"
    "O<pcenter> ENDSUB\n";

